def diff(dr, dc, wrap):
    extra=[]; miss=[]
    s1set=set(s1cells); s2set=set(s2cells)
    for r,c in s1cells:
        cc = (c+dc)%C if wrap else c+dc
        rr = r+dr
        if 0<=rr<R and (wrap or 0<=cc<C):
            if (rr,cc) not in s2set: miss.append((r,c))
    for r,c in s2cells:
        cc = (c-dc)%C if wrap else c-dc
        rr = r-dr
        if 0<=rr<R and (wrap or 0<=cc<C):
            if (rr,cc) not in s1set: extra.append((r,c))
    return sorted(miss), sorted(extra)
